'use strict';
const el=document.querySelector('#orbit-config');
if(el){const config=JSON.parse(el.textContent);let selected=0;const nodes=[...document.querySelectorAll('[data-cap]')];function choose(i,announce=true){selected=i;const cap=config.caps[i];document.querySelector('#cap-counter').textContent=String(i+1).padStart(2,'0');document.querySelector('#cap-number').textContent=String(i+1).padStart(2,'0');document.querySelector('#cap-title').textContent=cap.title;document.querySelector('#cap-description').textContent=cap.description;const list=document.querySelector('#cap-outputs');list.replaceChildren(...cap.outputs.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));document.querySelector('#cap-link').href=cap.url;nodes.forEach(b=>{const active=Number(b.dataset.cap)===i;b.setAttribute('aria-pressed',String(active));b.classList.toggle('active',active)});if(announce)document.querySelector('#cap-announcement').textContent=cap.title;document.dispatchEvent(new CustomEvent('orbit:capability',{detail:{index:i}}));}
nodes.forEach(b=>{b.addEventListener('click',()=>choose(Number(b.dataset.cap)));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const delta=['ArrowRight','ArrowDown'].includes(e.key)?1:-1;const next=(selected+delta+6)%6;choose(next);const group=b.classList.contains('cap-node')?'.cap-node':'.cap-pagination button';document.querySelectorAll(group)[next].focus()}})});
const stages=[...document.querySelectorAll('[data-stage]')];const dots=[...document.querySelectorAll('.stage-dots a')];let scheduled=false;let previousStage=-1;function updateStage(){scheduled=false;const aim=window.innerHeight*.45;let current=0;let min=Infinity;stages.forEach((e,i)=>{const distance=Math.abs(e.getBoundingClientRect().top-aim);if(distance<min){min=distance;current=i}});document.querySelector('#stage-number').textContent=String(current+1).padStart(2,'0');document.querySelector('#stage-name').textContent=config.stages[current];stages.forEach((e,i)=>e.classList.toggle('is-current',i===current));dots.forEach((e,i)=>{e.classList.toggle('active',i===current);if(i===current)e.setAttribute('aria-current','step');else e.removeAttribute('aria-current')});if(current!==previousStage){previousStage=current;document.dispatchEvent(new CustomEvent('orbit:stage',{detail:{index:current}}))}}window.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateStage)}},{passive:true});window.addEventListener('resize',updateStage);updateStage();}
